insomnia.test('Login retorna 200', () => {
  insomnia.expect(insomnia.response.code).to.eql(200);
});

insomnia.test('login define o cookie accessToken', () => {
  const cookie = insomnia.response.headers.find(header => header.key.toLowerCase() === 'set-cookie');
  insomnia.expect(cookie, 'Set-Cookie').to.exist;
  insomnia.expect(cookie.value).to.include('accessToken=');
  insomnia.expect(cookie.value.toLowerCase()).to.include('httponly');
});

insomnia.test('Criação retorna 201', () => {
  insomnia.expect(insomnia.response.code).to.eql(201);
});

if (insomnia.response.code === 201) {
  const shortUrl = insomnia.response.json().response;
  const match = typeof shortUrl === 'string' && shortUrl.match(/\/api\/([^/?#]+)$/);
  insomnia.test('retorna um link curto em /api/{code}', () => {
    insomnia.expect(match).to.be.ok;
  });
  if (match) insomnia.environment.set('anonymous_code', match[1]);
}

insomnia.test('Criação retorna 201', () => {
  insomnia.expect(insomnia.response.code).to.eql(201);
});

if (insomnia.response.code === 201) {
  const shortUrl = insomnia.response.json().response;
  const match = typeof shortUrl === 'string' && shortUrl.match(/\/api\/([^/?#]+)$/);
  insomnia.test('retorna um link curto em /api/{code}', () => {
    insomnia.expect(match).to.be.ok;
  });
  if (match) insomnia.environment.set('owner_code', match[1]);
}

insomnia.test('Redirecionamento retorna 302', () => {
  insomnia.expect(insomnia.response.code).to.eql(302);
});

insomnia.test('Location aponta para a URL original', () => {
  const location = insomnia.response.headers.find(header => header.key.toLowerCase() === 'location');
  insomnia.expect(location, 'Location').to.exist;
  insomnia.expect(location.value).to.eql(insomnia.environment.get('original_url'));
});

insomnia.test('Histórico autenticado retorna 200', () => {
  insomnia.expect(insomnia.response.code).to.eql(200);
});

if (insomnia.response.code === 200) {
  const links = insomnia.response.json();
  const ownerCode = insomnia.environment.get('owner_code');
  const anonymousCode = insomnia.environment.get('anonymous_code');
  insomnia.test('inclui o link da conta e exclui o anônimo', () => {
    insomnia.expect(ownerCode).to.be.a('string').and.not.empty;
    insomnia.expect(anonymousCode).to.be.a('string').and.not.empty;
    insomnia.expect(links).to.be.an('array');
    insomnia.expect(links.some(link => link.code === ownerCode)).to.eql(true);
    insomnia.expect(links.some(link => link.code === anonymousCode)).to.eql(false);
  });
}

insomnia.test('Estatísticas do proprietário retornam 200', () => {
  insomnia.expect(insomnia.response.code).to.eql(200);
});

if (insomnia.response.code === 200) {
  const body = insomnia.response.json();
  insomnia.test('retorna data, cliques e URL original', () => {
    insomnia.expect(body.date).to.be.a('string');
    insomnia.expect(body.clickCount).to.be.a('number').and.to.be.at.least(0);
    insomnia.expect(body.urlOriginal).to.eql(insomnia.environment.get('original_url'));
  });
}

insomnia.test('Estatísticas de link anônimo não são acessíveis à conta', () => {
  insomnia.expect(insomnia.response.code).to.eql(404);
});

insomnia.test('Outra conta não acessa as estatísticas do proprietário', () => {
  insomnia.expect(insomnia.response.code).to.eql(404);
});

insomnia.test('Histórico da outra conta retorna 200', () => {
  insomnia.expect(insomnia.response.code).to.eql(200);
});

if (insomnia.response.code === 200) {
  const links = insomnia.response.json();
  const ownerCode = insomnia.environment.get('owner_code');
  const anonymousCode = insomnia.environment.get('anonymous_code');
  insomnia.test('exclui links do proprietário e anônimos', () => {
    insomnia.expect(ownerCode).to.be.a('string').and.not.empty;
    insomnia.expect(anonymousCode).to.be.a('string').and.not.empty;
    insomnia.expect(links).to.be.an('array');
    insomnia.expect(links.some(link => link.code === ownerCode)).to.eql(false);
    insomnia.expect(links.some(link => link.code === anonymousCode)).to.eql(false);
  });
}
